// Green Ecosystem — Premium + the Green Coin collectible-gift marketplace.
//
// The screen intentionally consumes only server-authoritative entitlements, prices and ownership.
// Emoji/CSS art is the lightweight fallback that works in web, Android and desktop before the future
// Lottie asset pack is downloaded; every catalogue item still carries a stable animation id from the API.
// Browser bundles load the visual layer lazily. Keeping this guarded prevents Node's native test
// runner from trying to interpret a .css file while importing finance_screen.ts.
if (typeof document !== "undefined") {
  // @ts-expect-error esbuild owns CSS modules in browser bundles; Node tests never execute this branch.
  void import("./green_ecosystem_screen.css");
}

