function randomOpId(): string {
  return typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
    ? crypto.randomUUID()
    : `green-${Date.now()}-${Math.trunc(Math.random() * 1e9)}`;
}

function local(value: LocalizedText | null | undefined, locale: Locale): string {
  if (!value) return "";
  return value[locale] || value.en || value.ru;
}

function safeOpen(raw: string): void {
  const href = safeUrl(raw);
  if (!href) return;
  const anchor = document.createElement("a");
  anchor.href = href;
  anchor.target = "_blank";
  anchor.rel = "noopener noreferrer";
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
}

function price(value: number, locale: Locale): string {
  return `${new Intl.NumberFormat(locale === "ru" ? "ru-RU" : "en-US").format(value)} GCN`;
}

function dateText(seconds: number, locale: Locale): string {
  try {
    return new Intl.DateTimeFormat(locale === "ru" ? "ru-RU" : "en-US", {
      day: "numeric",
      month: "long",
      year: "numeric",
    }).format(new Date(seconds * 1000));
  } catch {
    return "";
  }
}

function optionLabel(raw: string): string {
  return raw
    .split("-")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

function giftArt(item: GiftCatalogItem): HTMLElement {
  return el("span", {
    class: `gc-green-gift-art is-${item.rarity}`,
    "data-animation": item.animation.id,
    "aria-hidden": true,
  }, [el("span", { class: "gc-green-gift-emoji" }, [item.emoji])]);
}

function giftCard(
  item: GiftCatalogItem,
  locale: Locale,
  copy: Copy,
  onBuy: (button: HTMLButtonElement, status: HTMLElement) => void,
): HTMLElement {
  const state = statusLine();
  state.classList.add("gc-green-card-status");
  const buy = el("button", { type: "button", class: "gc-btn gc-btn-accent gc-green-buy" }, [
    icon("plus"),
    copy.buy,
  ]) as HTMLButtonElement;
  buy.addEventListener("click", () => onBuy(buy, state));
  return el("article", {
    class: `gc-green-gift-card segment-${item.segment} rarity-${item.rarity}`,
  }, [
    giftArt(item),
    el("div", { class: "gc-green-gift-copy" }, [
      el("div", { class: "gc-green-gift-head" }, [
        el("strong", {}, [local(item.name, locale)]),
        el("span", { class: `gc-green-rarity is-${item.rarity}` }, [item.rarity]),
      ]),
      el("p", {}, [local(item.animation, locale)]),
      el("div", { class: "gc-green-gift-foot" }, [
        el("strong", { class: "gc-green-price" }, [price(item.price_gcn, locale)]),
        buy,
      ]),
      state,
    ]),
  ]);
}

function appearanceEditor(
  premium: PremiumResult,
  deps: GreenEcosystemDeps,
  copy: Copy,
  onReload: () => void,
): HTMLElement {
  if (!premium.active || !premium.appearance) return el("div", { hidden: true });
  const selectFor = (values: string[], selected: string): HTMLSelectElement => {
    const select = el("select", { class: "gc-select" }) as HTMLSelectElement;
    for (const value of values) {
      const option = el("option", { value }, [optionLabel(value)]) as HTMLOptionElement;
      option.selected = value === selected;
      select.append(option);
    }
    return select;
  };
  const nickname = selectFor(premium.appearance_options.nickname_styles, premium.appearance.nickname_style);
  const frame = selectFor(premium.appearance_options.avatar_frames, premium.appearance.avatar_frame);
  const bubble = selectFor(premium.appearance_options.message_bubbles, premium.appearance.message_bubble);
  const customStatus = el("input", {
    class: "gc-input",
    type: "text",
    maxlength: "32",
    value: premium.appearance.custom_status,
    placeholder: "🌿 Green mode",
  }) as HTMLInputElement;
  const state = statusLine();
  const save = el("button", { type: "submit", class: "gc-btn gc-btn-accent" }, [icon("check"), copy.save]) as HTMLButtonElement;
  const form = el("form", { class: "gc-green-style-form" }, [
    el("label", { class: "gc-field" }, [el("span", { class: "gc-field-label" }, [copy.nickname]), nickname]),
    el("label", { class: "gc-field" }, [el("span", { class: "gc-field-label" }, [copy.frame]), frame]),
    el("label", { class: "gc-field" }, [el("span", { class: "gc-field-label" }, [copy.bubble]), bubble]),
    el("label", { class: "gc-field gc-green-status-field" }, [el("span", { class: "gc-field-label" }, [copy.status]), customStatus]),
    el("div", { class: "gc-green-reactions", "aria-label": "Premium reactions" }, premium.appearance_options.premium_reactions.map((reaction) =>
      el("span", { class: "gc-green-reaction" }, [reaction]),
    )),
    state,
    save,
  ]);
  form.addEventListener("submit", (event) => {
    event.preventDefault();
    save.disabled = true;
    state.textContent = copy.loading;
    void deps.api.patch<PremiumResult>("/v1/green/premium/appearance", {
      nickname_style: nickname.value,
      avatar_frame: frame.value,
      message_bubble: bubble.value,
      custom_status: customStatus.value.trim(),
    }).then(() => {
      deps.onChanged?.(copy.save);
      onReload();
    }, (err: unknown) => {
      state.textContent = describeError(err, deps.i18n);
      save.disabled = false;
    });
  });
  return el("section", { class: "gc-green-panel" }, [el("h3", {}, [copy.appearance]), form]);
}

function premiumView(
  premium: PremiumResult,
  deps: GreenEcosystemDeps,
  copy: Copy,
  onReload: () => void,
): HTMLElement {
  const locale = deps.i18n.locale;
  const heroClass = `gc-green-premium-hero${premium.active ? " is-active" : ""}`;
  const hero = el("section", { class: heroClass }, [
    el("div", { class: "gc-green-premium-mark", "aria-hidden": true }, ["🌿"]),
    el("div", { class: "gc-green-premium-main" }, [
      el("span", { class: "gc-green-kicker" }, [premium.active ? copy.active : copy.subscription]),
      el("h3", {}, [copy.subscription]),
      el("p", {}, [copy.subscriptionLead]),
      el("div", { class: "gc-green-premium-price" }, [
        el("strong", {}, [`${premium.plan.amount_display} ₽`]),
        el("span", {}, [copy.perMonth]),
      ]),
      ...(premium.active && premium.subscription
        ? [el("p", { class: "gc-green-premium-until" }, [
            `${copy.until} ${dateText(premium.subscription.current_period_end, locale)}`,
          ])]
        : []),
    ]),
    ...(premium.appearance?.early_sponsor
      ? [el("span", { class: "gc-green-sponsor" }, [
          `✨ ${copy.earlySponsor}${premium.appearance.early_sponsor_number ? ` #${premium.appearance.early_sponsor_number}` : ""}`,
        ])]
      : []),
  ]);
  const benefits = el("section", { class: "gc-green-panel" }, [
    el("div", { class: "gc-green-benefits" }, copy.benefits.map((benefit) =>
      el("div", { class: "gc-green-benefit" }, [el("span", { "aria-hidden": true }, ["✓"]), el("p", {}, [benefit])]),
    )),
  ]);
  const actionState = statusLine();
  const actionArea = el("section", { class: "gc-green-subscription-actions" });
  if (!premium.active) {
    if (premium.checkout_available) {
      const subscribe = el("button", { type: "button", class: "gc-btn gc-btn-accent gc-green-subscribe" }, [
        icon("spark"),
        copy.subscribe,
      ]) as HTMLButtonElement;
      subscribe.addEventListener("click", () => {
        subscribe.disabled = true;
        actionState.textContent = copy.loading;
        void deps.api.post<CheckoutResult>("/v1/green/premium/checkout", { client_op_id: randomOpId() }).then((result) => {
          actionState.textContent = "";
          subscribe.disabled = false;
          safeOpen(result.checkout_url);
        }, (err: unknown) => {
          actionState.textContent = describeError(err, deps.i18n);
          subscribe.disabled = false;
        });
      });
      actionArea.append(subscribe);
    } else {
      actionArea.append(el("p", { class: "gc-green-provider-note" }, [copy.unavailable]));
    }
  } else if (premium.subscription?.auto_renew && !premium.subscription.cancel_at_period_end) {
    const cancel = el("button", { type: "button", class: "gc-btn gc-btn-quiet" }, [copy.cancelRenewal]) as HTMLButtonElement;
    cancel.addEventListener("click", () => {
      cancel.disabled = true;
      actionState.textContent = copy.loading;
      void deps.api.post<PremiumResult>("/v1/green/premium/cancel", {}).then(() => {
        actionState.textContent = copy.cancellationQueued;
        onReload();
      }, (err: unknown) => {
        actionState.textContent = describeError(err, deps.i18n);
        cancel.disabled = false;
      });
    });
    actionArea.append(cancel);
  } else {
    actionArea.append(el("p", { class: "gc-green-provider-note" }, [copy.cancellationQueued]));
  }
  actionArea.append(actionState);
  return el("div", { class: "gc-green-view" }, [
    hero,
    benefits,
    actionArea,
    appearanceEditor(premium, deps, copy, onReload),
  ]);
}

function catalogueView(
  catalog: GiftCatalogResult,
  deps: GreenEcosystemDeps,
  copy: Copy,
  onInventoryChanged: () => void,
): HTMLElement {
  const locale = deps.i18n.locale;
  const grid = el("div", { class: "gc-green-gift-grid" });
  const filters = el("div", { class: "gc-green-filters", role: "tablist" });
  const segments: Array<[string, string]> = [
    ["all", copy.all],
    ["basic", copy.basic],
    ["medium", copy.medium],
    ["premium", copy.premiumSegment],
    ["elite", copy.elite],
  ];
  let active = "all";
  const render = (): void => {
    clear(grid);
    for (const item of catalog.items) {
      if (active !== "all" && item.segment !== active) continue;
      grid.append(giftCard(item, locale, copy, (button, state) => {
        button.disabled = true;
        state.textContent = copy.buying;
        void deps.api.post<OperationResult>("/v1/green/gifts/purchase", {
          sku: item.id,
          client_op_id: randomOpId(),
        }).then(() => {
          state.textContent = copy.bought;
          button.disabled = false;
          onInventoryChanged();
          deps.onChanged?.(copy.bought);
        }, (err: unknown) => {
          state.textContent = describeError(err, deps.i18n);
          button.disabled = false;
        });
      }));
    }
  };
  for (const [id, label] of segments) {
    const button = el("button", {
      type: "button",
      class: `gc-green-filter${id === active ? " is-active" : ""}`,
      role: "tab",
      "aria-selected": id === active,
    }, [label]) as HTMLButtonElement;
    button.addEventListener("click", () => {
      active = id;
      for (const node of Array.from(filters.querySelectorAll(".gc-green-filter"))) {
        const selected = node === button;
        node.classList.toggle("is-active", selected);
        node.setAttribute("aria-selected", selected ? "true" : "false");
      }
      render();
    });
    filters.append(button);
  }
  render();
  return el("div", { class: "gc-green-view" }, [
    el("section", { class: "gc-green-market-intro" }, [
      el("div", {}, [
        el("span", { class: "gc-green-kicker" }, [`${catalog.count} ${copy.pieces}`]),
        el("h3", {}, [copy.gifts]),
        el("p", {}, [copy.marketplaceLead]),
      ]),
      el("div", { class: "gc-green-market-range" }, [
        el("span", {}, [price(catalog.min_price_gcn, locale)]),
        el("span", {}, ["→"]),
        el("strong", {}, [price(catalog.max_price_gcn, locale)]),
      ]),
    ]),
    el("p", { class: "gc-green-refund-note" }, ["↻ ", copy.exactRefund]),
    filters,
    grid,
  ]);
}

function collectionView(
  inventory: GiftInventoryResult,
  contacts: ContactRow[],
  deps: GreenEcosystemDeps,
  copy: Copy,
  onReload: () => void,
): HTMLElement {
  const locale = deps.i18n.locale;
  if (inventory.gifts.length === 0) {
    return el("div", { class: "gc-green-view gc-green-empty" }, [
      el("span", { class: "gc-green-empty-art", "aria-hidden": true }, ["🎁"]),
      el("p", {}, [copy.emptyCollection]),
    ]);
  }
  const list = el("div", { class: "gc-green-collection" });
  for (const gift of inventory.gifts) {
    const item = gift.catalog;
    if (!item) continue;
    const recipient = el("select", { class: "gc-select" }) as HTMLSelectElement;
    recipient.append(el("option", { value: "" }, [contacts.length ? copy.chooseContact : copy.noContacts]));
    for (const contact of contacts.filter((row) => !row.is_bot)) {
      recipient.append(el("option", { value: String(contact.id) }, [contact.alias || contact.name || `@${contact.username}`]));
    }
    const note = el("input", {
      class: "gc-input",
      type: "text",
      maxlength: "256",
      placeholder: copy.note,
    }) as HTMLInputElement;
    const state = statusLine();
    const send = el("button", { type: "button", class: "gc-btn gc-btn-accent" }, [icon("send"), copy.send]) as HTMLButtonElement;
    const convert = el("button", { type: "button", class: "gc-btn gc-btn-quiet" }, [icon("swap"), copy.convert]) as HTMLButtonElement;
    send.disabled = contacts.filter((row) => !row.is_bot).length === 0;
    send.addEventListener("click", () => {
      const toUserId = Number(recipient.value);
      if (!Number.isInteger(toUserId) || toUserId <= 0) {
        state.textContent = copy.chooseContact;
        return;
      }
      send.disabled = true;
      convert.disabled = true;
      state.textContent = copy.loading;
      void deps.api.post<OperationResult>(`/v1/green/gifts/${gift.id}/send`, {
        to_user_id: toUserId,
        note: note.value.trim(),
        client_op_id: randomOpId(),
      }).then(() => {
        deps.onChanged?.(copy.sent);
        onReload();
      }, (err: unknown) => {
        state.textContent = describeError(err, deps.i18n);
        send.disabled = false;
        convert.disabled = false;
      });
    });
    convert.addEventListener("click", () => {
      const confirmFn = (globalThis as { confirm?: (message: string) => boolean }).confirm;
      if (typeof confirmFn === "function" && !confirmFn(copy.convertConfirm)) return;
      send.disabled = true;
      convert.disabled = true;
      state.textContent = copy.converting;
      void deps.api.post<OperationResult>(`/v1/green/gifts/${gift.id}/convert`, {
        client_op_id: randomOpId(),
      }).then(() => {
        deps.onChanged?.(copy.converted);
        onReload();
      }, (err: unknown) => {
        state.textContent = describeError(err, deps.i18n);
        send.disabled = false;
        convert.disabled = false;
      });
    });
    list.append(el("article", { class: `gc-green-owned rarity-${item.rarity}` }, [
      giftArt(item),
      el("div", { class: "gc-green-owned-main" }, [
        el("div", { class: "gc-green-gift-head" }, [
          el("strong", {}, [local(item.name, locale)]),
          el("span", { class: `gc-green-rarity is-${item.rarity}` }, [item.rarity]),
        ]),
        el("p", { class: "gc-green-owned-price" }, [price(gift.price_gcn, locale)]),
        el("div", { class: "gc-green-send-form" }, [recipient, note]),
        el("div", { class: "gc-green-owned-actions" }, [send, convert]),
        state,
      ]),
    ]));
  }
  return el("div", { class: "gc-green-view" }, [list]);
}

export function openGreenEcosystem(deps: GreenEcosystemDeps): void {
  const copy = COPY[deps.i18n.locale];
  const globalStatus = statusLine();
  globalStatus.textContent = copy.loading;
  const tabs = el("nav", { class: "gc-green-tabs", "aria-label": copy.title });
  const content = el("div", { class: "gc-green-content", "aria-busy": "true" });
  const panel = sheet(deps.i18n, copy.title, copy.hint, [tabs, globalStatus, content], deps.closeSheet);
  panel.classList.add("gc-green-ecosystem-sheet");
  deps.openSheet(panel);

  let premium: PremiumResult | null = null;
  let catalog: GiftCatalogResult | null = null;
  let inventory: GiftInventoryResult = { gifts: [] };
  let contacts: ContactRow[] = [];
  let active: "premium" | "gifts" | "collection" = "premium";
  let loadVersion = 0;

  const render = (): void => {
    if (!premium || !catalog) return;
    content.setAttribute("aria-busy", "false");
    clear(content);
    if (active === "premium") content.append(premiumView(premium, deps, copy, () => void load()));
    else if (active === "gifts") content.append(catalogueView(catalog, deps, copy, () => void loadInventory()));
    else content.append(collectionView(inventory, contacts, deps, copy, () => void load()));
  };

  const loadInventory = async (): Promise<void> => {
    try {
      inventory = await deps.api.get<GiftInventoryResult>("/v1/green/gifts");
      if (active === "collection") render();
    } catch {
      // The primary screen stays useful even if the collection refresh alone fails. A full retry below
      // still exposes the error; purchase success remains visible in the card status.
    }
  };

  const load = async (): Promise<void> => {
    const version = ++loadVersion;
    content.setAttribute("aria-busy", "true");
    globalStatus.textContent = copy.loading;
    try {
      const [premiumResult, catalogResult, inventoryResult, contactResult] = await Promise.all([
        deps.api.get<PremiumResult>("/v1/green/premium"),
        deps.api.get<GiftCatalogResult>("/v1/green/gifts/catalog"),
        deps.api.get<GiftInventoryResult>("/v1/green/gifts"),
        deps.api.get<unknown>("/v1/contacts").catch(() => []),
      ]);
      if (version !== loadVersion) return;
      premium = premiumResult;
      catalog = catalogResult;
      inventory = inventoryResult;
      contacts = Array.isArray(contactResult) ? (contactResult as ContactRow[]) : [];
      globalStatus.textContent = "";
      render();
    } catch (err) {
      if (version !== loadVersion) return;
      clear(content);
      const retry = el("button", { type: "button", class: "gc-btn gc-btn-accent" }, [icon("refresh"), copy.retry]);
      retry.addEventListener("click", () => void load());
      content.append(el("div", { class: "gc-green-load-error" }, [
        el("strong", {}, [copy.loadFailed]),
        el("p", {}, [describeError(err, deps.i18n)]),
        retry,
      ]));
      content.setAttribute("aria-busy", "false");
      globalStatus.textContent = "";
    }
  };

  const tabData: Array<["premium" | "gifts" | "collection", string, string]> = [
    ["premium", copy.premium, "🌿"],
    ["gifts", copy.gifts, "🎁"],
    ["collection", copy.collection, "💎"],
  ];
  for (const [id, label, mark] of tabData) {
    const button = el("button", {
      type: "button",
      class: `gc-green-tab${id === active ? " is-active" : ""}`,
      "aria-current": id === active ? "page" : undefined,
    }, [el("span", { "aria-hidden": true }, [mark]), el("span", {}, [label])]) as HTMLButtonElement;
    button.addEventListener("click", () => {
      active = id;
      for (const node of Array.from(tabs.querySelectorAll(".gc-green-tab"))) {
        const selected = node === button;
        node.classList.toggle("is-active", selected);
        if (selected) node.setAttribute("aria-current", "page");
        else node.removeAttribute("aria-current");
      }
      render();
    });
    tabs.append(button);
  }

  void load();
}


export interface GreenEcosystemScreenDeps {
  api: ApiLike;
  i18n: I18n;
  onBack(): void;
  onChanged?(message: string): void;
}

/** Dedicated left-rail Premium destination. Before purchase it opens directly on the conversion
 * screen; after activation the same route exposes every appearance control plus gifts/collection. */
export function createGreenEcosystemScreen(deps: GreenEcosystemScreenDeps): {
  root: HTMLElement;
  destroy(): void;
} {
  const copy = COPY[deps.i18n.locale];
  const adapter: GreenEcosystemDeps = {
    api: deps.api,
    i18n: deps.i18n,
    openSheet() {},
    closeSheet() {},
    ...(deps.onChanged ? { onChanged: deps.onChanged } : {}),
  };
  const title = el("div", { class: "gc-green-page-title" }, [
    el("button", { type: "button", class: "gc-icon-btn gc-green-page-back", title: "Назад", "aria-label": "Назад" }, [icon("back")]),
    el("div", {}, [
      el("span", { class: "gc-green-kicker" }, ["GREEN ECOSYSTEM"]),
      el("h1", {}, [copy.subscription]),
      el("p", {}, [copy.hint]),
    ]),
    el("div", { class: "gc-green-page-emblem", "aria-hidden": true }, [
      el("span", {}, ["🌿"]), el("i"), el("i"), el("i"),
    ]),
  ]);
  (title.querySelector(".gc-green-page-back") as HTMLButtonElement).addEventListener("click", deps.onBack);

  const tabs = el("nav", { class: "gc-green-tabs", "aria-label": copy.title });
  const globalStatus = statusLine();
  globalStatus.textContent = copy.loading;
  const content = el("div", { class: "gc-green-content", "aria-busy": "true" });
  const root = el("main", { class: "gc-green-ecosystem-page" }, [
    el("div", { class: "gc-green-page-bg", "aria-hidden": true }, [
      el("span"), el("span"), el("span"), el("span"), el("span"),
    ]),
    title,
    el("section", { class: "gc-green-page-card" }, [tabs, globalStatus, content]),
  ]);

  let premium: PremiumResult | null = null;
  let catalog: GiftCatalogResult | null = null;
  let inventory: GiftInventoryResult = { gifts: [] };
  let contacts: ContactRow[] = [];
  let active: "premium" | "gifts" | "collection" = "premium";
  let loadVersion = 0;
  let disposed = false;

  const render = (): void => {
    if (disposed || !premium || !catalog) return;
    content.setAttribute("aria-busy", "false");
    clear(content);
    if (active === "premium") content.append(premiumView(premium, adapter, copy, () => void load()));
    else if (active === "gifts") content.append(catalogueView(catalog, adapter, copy, () => void loadInventory()));
    else content.append(collectionView(inventory, contacts, adapter, copy, () => void load()));
  };

  const loadInventory = async (): Promise<void> => {
    try {
      inventory = await deps.api.get<GiftInventoryResult>("/v1/green/gifts");
      if (!disposed && active === "collection") render();
    } catch { /* the catalogue and Premium screen remain usable */ }
  };

  const load = async (): Promise<void> => {
    const version = ++loadVersion;
    content.setAttribute("aria-busy", "true");
    globalStatus.textContent = copy.loading;
    try {
      const [premiumResult, catalogResult, inventoryResult, contactResult] = await Promise.all([
        deps.api.get<PremiumResult>("/v1/green/premium"),
        deps.api.get<GiftCatalogResult>("/v1/green/gifts/catalog"),
        deps.api.get<GiftInventoryResult>("/v1/green/gifts"),
        deps.api.get<unknown>("/v1/contacts").catch(() => []),
      ]);
      if (disposed || version !== loadVersion) return;
      const becameActive = premium?.active === false && premiumResult.active === true;
      premium = premiumResult;
      catalog = catalogResult;
      inventory = inventoryResult;
      contacts = Array.isArray(contactResult) ? contactResult as ContactRow[] : [];
      globalStatus.textContent = becameActive ? copy.active : "";
      render();
    } catch (err) {
      if (disposed || version !== loadVersion) return;
      clear(content);
      const retry = el("button", { type: "button", class: "gc-btn gc-btn-accent" }, [icon("refresh"), copy.retry]);
      retry.addEventListener("click", () => void load());
      content.append(el("div", { class: "gc-green-load-error" }, [
        el("strong", {}, [copy.loadFailed]),
        el("p", {}, [describeError(err, deps.i18n)]),
        retry,
      ]));
      content.setAttribute("aria-busy", "false");
      globalStatus.textContent = "";
    }
  };

  const tabData: Array<["premium" | "gifts" | "collection", string, string]> = [
    ["premium", copy.premium, "🌿"],
    ["gifts", copy.gifts, "🎁"],
    ["collection", copy.collection, "💎"],
  ];
  for (const [id, label, mark] of tabData) {
    const button = el("button", {
      type: "button",
      class: `gc-green-tab${id === active ? " is-active" : ""}`,
      "aria-current": id === active ? "page" : undefined,
    }, [el("span", { "aria-hidden": true }, [mark]), el("span", {}, [label])]) as HTMLButtonElement;
    button.addEventListener("click", () => {
      active = id;
      for (const node of Array.from(tabs.querySelectorAll(".gc-green-tab"))) {
        const selected = node === button;
        node.classList.toggle("is-active", selected);
        if (selected) node.setAttribute("aria-current", "page"); else node.removeAttribute("aria-current");
      }
      render();
    });
    tabs.append(button);
  }

  const refreshOnReturn = (): void => {
    if (typeof document === "undefined" || document.visibilityState === "visible") void load();
  };
  globalThis.addEventListener?.("focus", refreshOnReturn);
  if (typeof document !== "undefined") document.addEventListener("visibilitychange", refreshOnReturn);
  const poll = setInterval(() => { if (!premium?.active) void load(); }, 5_000);
  (poll as unknown as { unref?: () => void }).unref?.();
  void load();

  return {
    root,
    destroy() {
      disposed = true;
      loadVersion += 1;
      clearInterval(poll);
      globalThis.removeEventListener?.("focus", refreshOnReturn);
      if (typeof document !== "undefined") document.removeEventListener("visibilitychange", refreshOnReturn);
    },
  };
}
